#!/usr/bin/env node
// Provenance of FormLogic's server sandbox, generated by the build and never
// written by hand (the hand-kept runtime/host/SOURCE.json it replaces had
// drifted: it named a rustc the build script did not use).
//
// Each component a build produces leaves a record under .runtime-source/sandbox/:
// the guest (built from ZIPP source) and each launcher (which embeds that
// guest), possibly in different CI jobs. `provenance` merges the records with
// the installed Softn release into formlogic/backend/bin/runtime/SOURCE.json,
// which ships beside the launchers in the distributable zip; `check` proves
// the files there, that record and the installed Softn release agree.
//
//   node scripts/runtime-provenance.mjs toolchain                    the Rust toolchain ZIPP's release was built with
//   node scripts/runtime-provenance.mjs fragment guest               record the guest just built
//   node scripts/runtime-provenance.mjs fragment linux|windows [--rustc "<rustc -Vv>"]
//                                                                    record a launcher just built
//   node scripts/runtime-provenance.mjs prune linux|windows          drop that launcher unless it embeds the recorded guest
//   node scripts/runtime-provenance.mjs provenance                   merge the records into bin/runtime/SOURCE.json
//   node scripts/runtime-provenance.mjs check                        files, SOURCE.json and the installed release agree
//
// check also compares the Softn archive with a frozen release record when
// SOFTN_FROZEN names one (a CI run's resolve job), and takes --require
// linux,windows and --ci for packaging. `check --deployed` asks only what a
// running backend needs: each launcher in bin/runtime is the recorded one,
// built from the ZIPP release the installed Softn release names. The guest
// file and the Softn archive digest are build inputs, so it skips them (a
// source checkout given a release zip's launchers has no guest, and a newer
// Softn release naming the same ZIPP runs the same sandbox).
import { createHash } from 'node:crypto';
import { spawnSync } from 'node:child_process';
import { existsSync, mkdirSync, readdirSync, readFileSync, rmSync, writeFileSync } from 'node:fs';
import { dirname, resolve } from 'node:path';
import { fileURLToPath } from 'node:url';
import { zippReleaseIdentity } from '../formlogic/ui/scripts/hosted-runtime-artifact.mjs';
import { loadFrozen } from './fetch-softn-release.mjs';
import { ZIPP_LOCK, ZIPP_REPOSITORY } from './zipp-source.mjs';

export const PROVENANCE_FORMAT = 1;
export const GUEST = Object.freeze({ artifact: 'formlogic-runtime-guest.wasm', target: 'wasm32-wasip1' });
export const LAUNCHERS = Object.freeze({
  linux: Object.freeze({ artifact: 'formlogic-runtime-linux-x86_64', target: 'x86_64-unknown-linux-musl' }),
  windows: Object.freeze({ artifact: 'formlogic-runtime-windows-x86_64.exe', target: 'x86_64-pc-windows-msvc' }),
});

const sha256 = (bytes) => createHash('sha256').update(bytes).digest('hex');
const short = (value) => String(value ?? '(none)').slice(0, 12);
const readJson = (file) => JSON.parse(readFileSync(file, 'utf8'));

export function runtimePaths(root) {
  return {
    current: resolve(root, '.runtime-source/softn-release/current.json'),
    buildInfo: resolve(root, 'formlogic/ui/vendor/zipp-wasm/BUILD-INFO.txt'),
    stamp: resolve(root, '.runtime-source/zipp/source.json'),
    fragments: resolve(root, '.runtime-source/sandbox'),
    guestWasm: resolve(root, 'formlogic/runtime/host', GUEST.artifact),
    guestToml: resolve(root, 'formlogic/runtime/guest/Cargo.toml'),
    guestLock: resolve(root, 'formlogic/runtime/guest/Cargo.lock'),
    hostLock: resolve(root, 'formlogic/runtime/host/Cargo.lock'),
    bin: resolve(root, 'formlogic/backend/bin/runtime'),
    source: resolve(root, 'formlogic/backend/bin/runtime/SOURCE.json'),
  };
}

/** `rustc -Vv` as {rustc: its first line, host: the triple it runs on}; the host is why a guest built on Windows differs from one built on Linux. */
export function rustcInfo(verbose) {
  const lines = String(verbose ?? '').replace(/\r\n/g, '\n').trim().split('\n');
  if (!/^rustc \d+\.\d+\.\d+/.test(lines[0] ?? '')) throw new Error(`Not rustc -Vv output: ${String(verbose).trim().slice(0, 120) || '(empty)'}`);
  return { rustc: lines[0].trim(), rustcHost: /^host: (.+)$/m.exec(lines.join('\n'))?.[1]?.trim() ?? null };
}

/** The toolchain name (X.Y.Z) in a `rustc X.Y.Z (...)` line. */
export function toolchainOf(rustc) {
  const version = /^rustc (\d+\.\d+\.\d+)/.exec(String(rustc ?? ''))?.[1];
  if (!version) throw new Error(`No rustc version in ${JSON.stringify(rustc)}.`);
  return version;
}

/** Who built it: this CI run (with the runner image), or a developer's machine. */
export function buildContext(env = process.env) {
  if (env.GITHUB_ACTIONS !== 'true') return { by: 'local', runId: null, runUrl: null, runner: 'local' };
  const runUrl = env.GITHUB_RUN_ID ? `${env.GITHUB_SERVER_URL ?? 'https://github.com'}/${env.GITHUB_REPOSITORY}/actions/runs/${env.GITHUB_RUN_ID}` : null;
  return { by: 'ci', runId: env.GITHUB_RUN_ID ?? null, runUrl, runner: env.ImageOS ? `${env.ImageOS}/${env.ImageVersion ?? 'unknown'}` : 'github-hosted' };
}

/** How the zipp-vm dependency is compiled into the guest, from its Cargo.toml. */
export function guestFeatures(tomlText) {
  const line = String(tomlText).replace(/\r\n/g, '\n').split('\n').find((candidate) => /^\s*zipp-vm\s*=/.test(candidate));
  if (!line) throw new Error('formlogic/runtime/guest/Cargo.toml has no zipp-vm dependency.');
  const features = /\bfeatures\s*=\s*\[([^\]]*)\]/.exec(line.replace(/default-features\s*=\s*\w+/, ''))?.[1];
  return {
    defaultFeatures: !/default-features\s*=\s*false/.test(line),
    features: features ? [...features.matchAll(/"([^"]+)"/g)].map((match) => match[1]) : [],
  };
}

/** The wasmtime version FormLogic's committed host/Cargo.lock builds the launcher with. */
export function wasmtimeVersion(lockText) {
  return /\[\[package\]\]\r?\nname = "wasmtime"\r?\nversion = "([^"]+)"/.exec(String(lockText))?.[1] ?? null;
}

/**
 * How the Linux launcher is linked, read from its own ELF program headers (no
 * `file` needed, so a host without it cannot skip the check). A PT_INTERP
 * names the dynamic loader the binary needs, so it runs only where that loader
 * exists, and is refused; without one it is static (ET_EXEC) or static-pie
 * (ET_DYN) and runs on any x86-64 Linux.
 */
export function elfLinkage(bytes) {
  const elf = Buffer.from(bytes);
  if (elf.length < 64 || elf.readUInt32BE(0) !== 0x7f454c46) throw new Error('The Linux launcher is not an ELF binary.');
  if (elf[4] !== 2 || elf[5] !== 1 || elf.readUInt16LE(18) !== 62) throw new Error('The Linux launcher is not a 64-bit little-endian x86-64 ELF binary.');
  const type = elf.readUInt16LE(16);
  const headers = Number(elf.readBigUInt64LE(32));
  const size = elf.readUInt16LE(54);
  const count = elf.readUInt16LE(56);
  if (size < 4 || headers + size * count > elf.length) throw new Error('The Linux launcher\'s ELF program headers are cut short.');
  for (let index = 0; index < count; index++) {
    if (elf.readUInt32LE(headers + index * size) === 3 /* PT_INTERP */) throw new Error('The Linux launcher is dynamically linked (it names an ELF interpreter); it must be a static musl binary.');
  }
  if (type === 2) return 'static';
  if (type === 3) return 'static-pie';
  throw new Error(`The Linux launcher is ELF type ${type}, not an executable.`);
}

/** The `rustc=` line of a ZIPP bundle's BUILD-INFO.txt, or null. */
export function buildInfoRustc(text) {
  return /^rustc=(.+)$/m.exec(String(text ?? '').replace(/\r\n/g, '\n'))?.[1]?.trim() || null;
}

export function guestFragment({ stamp, guestBytes, guestLockText, guestTomlText, rustcVerbose, env = process.env }) {
  if (!stamp || !/^[0-9a-f]{40}$/.test(stamp.revision ?? '')) throw new Error('No verified ZIPP source is recorded (.runtime-source/zipp/source.json): run node scripts/zipp-source.mjs first.');
  const context = buildContext(env);
  return {
    formatVersion: PROVENANCE_FORMAT,
    // cargoLock: which of ZIPP's locks seeded the guest's (its workspace lock, not the browser engine's).
    zipp: { repository: stamp.repository ?? ZIPP_REPOSITORY, release: stamp.release, version: stamp.version, revision: stamp.revision, cargoLock: stamp.cargoLock ?? ZIPP_LOCK, cargoLockSha256: stamp.cargoLockSha256 },
    guest: {
      artifact: GUEST.artifact,
      sha256: sha256(guestBytes),
      target: GUEST.target,
      ...rustcInfo(rustcVerbose),
      cargoLockSha256: sha256(guestLockText),
      ...guestFeatures(guestTomlText),
      runner: context.runner,
    },
    build: { by: context.by, runId: context.runId, runUrl: context.runUrl },
  };
}

export function launcherFragment({ platform, bytes, guestBytes, rustcVerbose, env = process.env }) {
  const launcher = LAUNCHERS[platform];
  if (!launcher) throw new Error(`Unknown launcher platform ${platform}; expected ${Object.keys(LAUNCHERS).join(' or ')}.`);
  const context = buildContext(env);
  const linkage = platform === 'linux' ? elfLinkage(bytes) : null;
  return {
    formatVersion: PROVENANCE_FORMAT,
    launcher: {
      artifact: launcher.artifact,
      sha256: sha256(bytes),
      target: launcher.target,
      ...rustcInfo(rustcVerbose),
      ...(linkage && { linkage }),
      guestSha256: sha256(guestBytes),
      runner: context.runner,
    },
    build: { by: context.by, runId: context.runId, runUrl: context.runUrl },
  };
}

/**
 * bin/runtime/SOURCE.json from the component records and the installed Softn
 * release (current.json). Refuses a guest built from another ZIPP than that
 * release names, and a launcher that embeds another guest. Only the build
 * time differs between two merges of the same records.
 */
export function mergeProvenance({ current, guest, launchers, formlogic, hostLockText, now = new Date() }) {
  let zipp;
  try { zipp = zippReleaseIdentity(current?.zipp); }
  catch (error) { throw new Error(`The installed Softn release names no ZIPP release: ${error.message} Run node scripts/fetch-softn-release.mjs.`); }
  if (!guest) throw new Error('No guest record (.runtime-source/sandbox/guest.json): build it (scripts/build-runtime.sh zipp-source guest) or install the sandbox-guest artifact.');
  for (const record of [guest, ...launchers]) {
    if (record.formatVersion !== PROVENANCE_FORMAT) throw new Error(`A sandbox build record has formatVersion ${record.formatVersion}; this script writes ${PROVENANCE_FORMAT}.`);
  }
  if (guest.zipp.release !== zipp.release || guest.zipp.revision !== zipp.revision) {
    throw new Error(`The guest was built from ZIPP ${guest.zipp.release} (${short(guest.zipp.revision)}); the installed Softn release ${current.tag} names ZIPP ${zipp.release} (${short(zipp.revision)}). Rebuild it: scripts/build-runtime.sh zipp-source guest, then the launchers.`);
  }
  if (!launchers.length) throw new Error('No launcher record (.runtime-source/sandbox/linux.json or windows.json): build one (scripts/build-runtime.sh linux|windows) or install its artifact.');
  const seen = new Set();
  for (const { launcher } of launchers) {
    if (seen.has(launcher.artifact)) throw new Error(`Two records describe ${launcher.artifact}.`);
    seen.add(launcher.artifact);
    if (launcher.guestSha256 !== guest.guest.sha256) {
      throw new Error(`${launcher.artifact} embeds guest ${short(launcher.guestSha256)}, not the recorded guest ${short(guest.guest.sha256)}: rebuild it after the guest (scripts/build-runtime.sh ${Object.keys(LAUNCHERS).find((key) => LAUNCHERS[key].artifact === launcher.artifact)}).`);
    }
  }
  const builds = [guest.build, ...launchers.map((record) => record.build)];
  // One CI run built every piece, or it is a local (or mixed) build: package-dist --release takes only the first.
  const oneRun = builds.every((build) => build.by === 'ci' && build.runId && build.runId === builds[0].runId);
  return {
    formatVersion: PROVENANCE_FORMAT,
    zipp: { repository: zipp.repository ?? ZIPP_REPOSITORY, release: zipp.release, version: zipp.version, revision: zipp.revision, sumsSha256: zipp.sumsSha256, cargoLock: guest.zipp.cargoLock ?? ZIPP_LOCK, cargoLockSha256: guest.zipp.cargoLockSha256 },
    softnRelease: { tag: current.tag ?? null, commit: current.commit ?? null, archiveSha256: current.sha256 ?? null },
    formlogic,
    guest: guest.guest,
    host: { wasmtime: wasmtimeVersion(hostLockText) },
    launchers: launchers.map((record) => record.launcher).sort((a, b) => a.artifact.localeCompare(b.artifact)),
    build: { by: oneRun ? 'ci' : 'local', runId: oneRun ? builds[0].runId : null, runUrl: oneRun ? builds[0].runUrl : null, builtAt: now.toISOString() },
  };
}

/**
 * Why the installed sandbox does not match SOURCE.json and the installed Softn
 * release; empty when it does. `binFiles` maps each formlogic-runtime-* file in
 * bin/runtime to its bytes, `guestBytes` is runtime/host's guest (or null).
 * `deployed` leaves out the build inputs (the guest file, the Softn archive).
 */
export function provenanceProblems({ source, current, frozen = null, guestBytes, binFiles, require = [], ci = false, deployed = false }) {
  const problems = [];
  if (source?.formatVersion !== PROVENANCE_FORMAT) return [`bin/runtime/SOURCE.json has formatVersion ${source?.formatVersion}; expected ${PROVENANCE_FORMAT}.`];
  const zipp = current?.zipp ?? {};
  const sameZipp = source.zipp?.release === zipp.release && source.zipp?.revision === zipp.revision;
  if (!sameZipp) {
    problems.push(`the sandbox was built from ZIPP ${source.zipp?.release} (${short(source.zipp?.revision)}); the installed Softn release ${current?.tag} names ZIPP ${zipp.release} (${short(zipp.revision)}): rebuild it (scripts/build-runtime.sh all) or install that release's sandbox`);
  }
  if (!deployed) {
    // The archive changes no sandbox byte: with the same ZIPP, recording it again is the whole fix.
    const recordAgain = 'record it again (scripts/build-runtime.sh provenance)';
    if (source.softnRelease?.archiveSha256 !== current?.sha256) {
      problems.push(`the sandbox was recorded against Softn archive ${short(source.softnRelease?.archiveSha256)}; the installed archive is ${short(current?.sha256)}: ${sameZipp ? `it is still ZIPP ${zipp.release}'s sandbox, so ${recordAgain}` : 'rebuild it for the ZIPP release above'}`);
    }
    if (frozen && source.softnRelease?.archiveSha256 !== frozen.archiveSha256) {
      problems.push(`the sandbox was recorded against Softn archive ${short(source.softnRelease?.archiveSha256)}; this run froze ${frozen.tag} (${short(frozen.archiveSha256)}): install that release, then ${recordAgain} if it names ZIPP ${source.zipp?.release}, or rebuild it`);
    }
    if (!guestBytes) problems.push(`formlogic/runtime/host/${GUEST.artifact} is missing`);
    else if (sha256(guestBytes) !== source.guest?.sha256) problems.push(`formlogic/runtime/host/${GUEST.artifact} is ${short(sha256(guestBytes))}; SOURCE.json records ${short(source.guest?.sha256)}`);
  }
  const recorded = new Map((source.launchers ?? []).map((launcher) => [launcher.artifact, launcher]));
  for (const [artifact, launcher] of recorded) {
    const bytes = binFiles.get(artifact);
    if (!bytes) problems.push(`${artifact} is recorded but missing`);
    else if (sha256(bytes) !== launcher.sha256) problems.push(`${artifact} is ${short(sha256(bytes))}; SOURCE.json records ${short(launcher.sha256)}`);
    if (launcher.guestSha256 !== source.guest?.sha256) problems.push(`${artifact} embeds guest ${short(launcher.guestSha256)}, not ${short(source.guest?.sha256)}`);
  }
  for (const artifact of binFiles.keys()) {
    if (!recorded.has(artifact)) problems.push(`${artifact} is in bin/runtime but not in SOURCE.json (built from another guest, or left from an older build): rebuild or remove it`);
  }
  for (const platform of require) {
    if (!recorded.has(LAUNCHERS[platform]?.artifact ?? platform)) problems.push(`the ${platform} launcher is not recorded`);
  }
  if (ci && source.build?.by !== 'ci') problems.push(`the sandbox was built by ${source.build?.by ?? '(unrecorded)'}, not by one CI run; a release ships only launchers CI built`);
  return problems;
}

// ── The filesystem side ──────────────────────────────────────────────────────

function run(command, args, options = {}) {
  const result = spawnSync(command, args, { encoding: 'utf8', ...options });
  return result.error || result.status !== 0 ? null : result.stdout;
}

function fragmentFile(root, kind) {
  return resolve(runtimePaths(root).fragments, `${kind}.json`);
}

function readFragment(root, kind) {
  const file = fragmentFile(root, kind);
  return existsSync(file) ? readJson(file) : null;
}

/**
 * The toolchain the installed ZIPP release was built with: the rustc its
 * bundle's BUILD-INFO names, which the Softn release's ZIPP record must repeat
 * (a record that does not is no evidence of the release toolchain). With no
 * Softn release installed (CI's Windows job), the one the guest was built with.
 */
export function toolchain(root) {
  const { current, buildInfo } = runtimePaths(root);
  const recorded = existsSync(current) ? readJson(current).zipp?.rustc ?? null : null;
  const built = existsSync(buildInfo) ? buildInfoRustc(readFileSync(buildInfo, 'utf8')) : null;
  if (built && recorded && built !== recorded) {
    throw new Error(`The installed ZIPP bundle's BUILD-INFO.txt names ${built}, but the Softn release's ZIPP record says ${recorded}: the record is not the bundle's, so ZIPP's release toolchain is not known. Fetch the Softn release again (node scripts/fetch-softn-release.mjs); if it persists, the release is at fault.`);
  }
  if (built ?? recorded) return toolchainOf(built ?? recorded);
  const guest = readFragment(root, 'guest');
  if (guest?.guest?.rustc) return toolchainOf(guest.guest.rustc);
  throw new Error('Cannot tell which Rust toolchain to build with: install the Softn release (node scripts/fetch-softn-release.mjs), whose ZIPP record names it, or the sandbox-guest artifact.');
}

export function writeFragment(root, kind, { rustcVerbose = null, env = process.env } = {}) {
  const paths = runtimePaths(root);
  if (!existsSync(paths.guestWasm)) throw new Error(`formlogic/runtime/host/${GUEST.artifact} is missing: build the guest first (scripts/build-runtime.sh guest).`);
  const guestBytes = readFileSync(paths.guestWasm);
  const verbose = rustcVerbose ?? run('rustc', ['-Vv']);
  if (!verbose) throw new Error('rustc -Vv failed; the toolchain that built this cannot be recorded.');
  let fragment;
  if (kind === 'guest') {
    if (!existsSync(paths.stamp)) throw new Error('No verified ZIPP source is recorded (.runtime-source/zipp/source.json): run node scripts/zipp-source.mjs first.');
    fragment = guestFragment({ stamp: readJson(paths.stamp), guestBytes, guestLockText: readFileSync(paths.guestLock, 'utf8'), guestTomlText: readFileSync(paths.guestToml, 'utf8'), rustcVerbose: verbose, env });
  } else {
    const launcher = LAUNCHERS[kind];
    if (!launcher) throw new Error(`Unknown sandbox component ${kind}; expected guest, linux or windows.`);
    const file = resolve(paths.bin, launcher.artifact);
    if (!existsSync(file)) throw new Error(`formlogic/backend/bin/runtime/${launcher.artifact} is missing.`);
    fragment = launcherFragment({ platform: kind, bytes: readFileSync(file), guestBytes, rustcVerbose: verbose, env });
  }
  mkdirSync(paths.fragments, { recursive: true });
  writeFileSync(fragmentFile(root, kind), JSON.stringify(fragment, null, 2) + '\n');
  return fragment;
}

/**
 * Removes `platform`'s launcher and its build record unless the record
 * describes that very file embedding the guest the guest record names.
 * scripts/build-runtime.sh all runs it for the Linux launcher it skips on
 * Windows without Docker: one left from an earlier build embeds another guest
 * (unless the guest came out byte-identical), and SOURCE.json records one
 * guest, so it could not be recorded beside the launcher just built, and the
 * provenance step would stop there. Returns the paths it removed.
 */
export function pruneLauncher(root, platform) {
  const launcher = LAUNCHERS[platform];
  if (!launcher) throw new Error(`Unknown launcher platform ${platform}; expected ${Object.keys(LAUNCHERS).join(' or ')}.`);
  const file = resolve(runtimePaths(root).bin, launcher.artifact);
  const record = readFragment(root, platform);
  const guest = readFragment(root, 'guest');
  const present = existsSync(file);
  if (present && record && guest && record.launcher?.guestSha256 === guest.guest?.sha256 && sha256(readFileSync(file)) === record.launcher?.sha256) return [];
  const removed = [];
  if (present) { rmSync(file); removed.push(`formlogic/backend/bin/runtime/${launcher.artifact}`); }
  if (record) { rmSync(fragmentFile(root, platform)); removed.push(`.runtime-source/sandbox/${platform}.json`); }
  return removed;
}

function formlogicCommit(root, env) {
  const commit = env.GITHUB_SHA || run('git', ['-C', root, 'rev-parse', 'HEAD'])?.trim() || null;
  const status = run('git', ['-C', root, 'status', '--porcelain', '--untracked-files=no']);
  return { commit, dirty: status === null ? null : status.trim() !== '' };
}

/** Merges the records present into bin/runtime/SOURCE.json, after proving each still describes the file beside it. */
export function writeProvenance(root, { env = process.env, formlogic = null, now = new Date() } = {}) {
  const paths = runtimePaths(root);
  if (!existsSync(paths.current)) throw new Error('No Softn release is installed (.runtime-source/softn-release/current.json): run node scripts/fetch-softn-release.mjs.');
  const guest = readFragment(root, 'guest');
  if (guest && (!existsSync(paths.guestWasm) || sha256(readFileSync(paths.guestWasm)) !== guest.guest.sha256)) {
    throw new Error(`formlogic/runtime/host/${GUEST.artifact} is not the guest .runtime-source/sandbox/guest.json records: rebuild (scripts/build-runtime.sh guest) or reinstall the sandbox-guest artifact.`);
  }
  const launchers = [];
  for (const [platform, launcher] of Object.entries(LAUNCHERS)) {
    const record = readFragment(root, platform);
    if (!record) continue;
    const file = resolve(paths.bin, launcher.artifact);
    if (!existsSync(file) || sha256(readFileSync(file)) !== record.launcher.sha256) {
      throw new Error(`formlogic/backend/bin/runtime/${launcher.artifact} is not the launcher .runtime-source/sandbox/${platform}.json records: rebuild it (scripts/build-runtime.sh ${platform}) or reinstall its artifact.`);
    }
    launchers.push(record);
  }
  const source = mergeProvenance({ current: readJson(paths.current), guest, launchers, formlogic: formlogic ?? formlogicCommit(root, env), hostLockText: readFileSync(paths.hostLock, 'utf8'), now });
  mkdirSync(paths.bin, { recursive: true });
  writeFileSync(paths.source, JSON.stringify(source, null, 2) + '\n');
  return source;
}

/** Checks the installed sandbox (see provenanceProblems); returns SOURCE.json. */
export async function checkSandbox(root, { frozen = process.env.SOFTN_FROZEN || null, require = [], ci = false, deployed = false } = {}) {
  const paths = runtimePaths(root);
  if (!existsSync(paths.source)) throw new Error('formlogic/backend/bin/runtime/SOURCE.json is missing: build the sandbox (scripts/build-runtime.sh all) or install a CI build, then write it (node scripts/runtime-provenance.mjs provenance).');
  if (!existsSync(paths.current)) throw new Error('No Softn release is installed (.runtime-source/softn-release/current.json): run node scripts/fetch-softn-release.mjs.');
  const source = readJson(paths.source);
  const binFiles = new Map();
  if (existsSync(paths.bin)) {
    for (const name of readdirSync(paths.bin)) if (name.startsWith('formlogic-runtime-')) binFiles.set(name, readFileSync(resolve(paths.bin, name)));
  }
  const problems = provenanceProblems({
    source,
    current: readJson(paths.current),
    frozen: await loadFrozen(frozen, root),
    guestBytes: existsSync(paths.guestWasm) ? readFileSync(paths.guestWasm) : null,
    binFiles,
    require,
    ci,
    deployed,
  });
  if (problems.length) throw new Error(`The server sandbox does not match its provenance:\n  - ${problems.join('\n  - ')}`);
  return source;
}

if (process.argv[1] && resolve(process.argv[1]) === fileURLToPath(import.meta.url)) {
  const args = process.argv.slice(2);
  const option = (name) => { const index = args.indexOf(name); return index >= 0 ? args[index + 1] : null; };
  const root = option('--root') ? resolve(option('--root')) : resolve(dirname(fileURLToPath(import.meta.url)), '..');
  try {
    switch (args[0]) {
      case 'toolchain':
        console.log(toolchain(root));
        break;
      case 'fragment': {
        const record = writeFragment(root, args[1], { rustcVerbose: option('--rustc') });
        const entry = record.guest ?? record.launcher;
        console.log(`recorded ${entry.artifact} ${entry.sha256.slice(0, 12)} (${entry.rustc}, ${record.build.by})`);
        break;
      }
      case 'prune': {
        const removed = pruneLauncher(root, args[1]);
        const artifact = LAUNCHERS[args[1]].artifact;
        console.log(removed.length
          ? `   removed ${removed.join(' and ')}: not a launcher for the guest just built (build it again: scripts/build-runtime.sh ${args[1]} smoke provenance, or install CI's sandbox-${args[1]})`
          : existsSync(resolve(runtimePaths(root).bin, artifact)) ? `   kept ${artifact}: it embeds the guest just built` : `   no ${artifact} to keep`);
        break;
      }
      case 'provenance': {
        const source = writeProvenance(root);
        console.log(`formlogic/backend/bin/runtime/SOURCE.json: ZIPP ${source.zipp.release} (${short(source.zipp.revision)}), guest ${short(source.guest.sha256)}, ${source.launchers.map((launcher) => `${launcher.artifact} ${short(launcher.sha256)}`).join(', ')}, built by ${source.build.by}`);
        break;
      }
      case 'check': {
        const source = await checkSandbox(root, { require: (option('--require') ?? '').split(',').filter(Boolean), ci: args.includes('--ci'), deployed: args.includes('--deployed') });
        console.log(`server sandbox OK${args.includes('--deployed') ? ' to run' : ''}: ZIPP ${source.zipp.release} (${short(source.zipp.revision)}) from Softn ${source.softnRelease.tag}; ${source.launchers.map((launcher) => launcher.artifact).join(', ')} embed guest ${short(source.guest.sha256)}; built by ${source.build.by}`);
        break;
      }
      default:
        console.error('usage: node scripts/runtime-provenance.mjs toolchain | fragment guest|linux|windows [--rustc "<rustc -Vv>"] | prune linux|windows | provenance | check [--require linux,windows] [--ci] [--deployed]');
        process.exit(2);
    }
  } catch (error) {
    console.error(`runtime-provenance: ${error.message}`);
    process.exit(1);
  }
}
